// Independent rules audit for The Thornbound Throne engine.  Run:  node games-src/thornbound/logic-test.js [--md]
// One block per numbered rule of RULES-CHECKLIST.md (that file is generated from the titles below with --md, so numbers always match).
// Every block builds its own state with TB.test helpers, acts through the public move API, and compares with the value the published rulebook
// demands (written here as literals, never read back from the engine's data). Failure line: "FAIL R<n>: expected <x>, got <y>".
// Exit code 1 when any rule fails.
const path=require('path');const SRC=process.env.LT_SRC||path.join(__dirname,'game','src');
require(path.join(SRC,'data.js'));require(path.join(SRC,'engine.js'));
const T=TB.test,I=TB.internal;
const SEC=[],RULES=[];let curSec='';
function S(name,note){curSec=name;SEC.push({name,note:note||'',first:RULES.length+1})}
function R(n,title,fn){if(RULES.length+1!==n)throw new Error('rule numbering: expected '+(RULES.length+1)+' got '+n);RULES.push({n,title,fn,sec:curSec})}
class Fail extends Error{constructor(e,g){super('expected '+JSON.stringify(e)+', got '+JSON.stringify(g));this.exp=e;this.got=g}}
function expect(got,exp){if(JSON.stringify(got)!==JSON.stringify(exp))throw new Fail(exp,got)}
function truth(cond,expDesc,gotDesc){if(!cond)throw new Fail(expDesc,gotDesc===undefined?'false':gotDesc)}
// ------------------------------------------------------------------ harness
const FAC=['nobility','clans','uprising','gathering'];
// faction card index within a seat: 0 ruse(0) 1 trader(0) 2..5 followers(1,2,3,4) 6 agent(5,deadly) 7 cavalry(5,flank) 8 war machine(5) 9..12 captains(6,7,8,9) 13 heir(10)
const RUSE=0,TRADER=1,F1=2,F2=3,F3=4,F4=5,AGENT=6,CAV=7,WM=8,C6=9,C7=10,C8=11,C9=12,HEIR=13;
const c=(seat,k)=>seat*100+k;
function game(np,o){o=o||{};const facs=o.facs||FAC.slice(0,np);return TB.newGame({players:facs.slice(0,np).map((f,i)=>({faction:f,name:'P'+i})),seed:o.seed||7,length:o.length,order:o.order||[...Array(np).keys()]})}
function setHand(G,seat,ids){for(const id of G.pl[seat].hand.slice())if(!ids.includes(id))T.put(G,id,'deck');for(const id of ids)T.put(G,id,'hand')}
function emptyHands(G){for(const P of G.pl)for(const id of P.hand.slice())T.put(G,id,'deck')}
function run(G,steps){T.run(G,steps)}
function ans(G,seat,m){return T.answer(G,seat,m)}
const kind=G=>{const p=TB.pending(G);return p?p.kind:null};
// pump: answer every pending question with policy[kind](moves,seat) (or policy['*']); a policy returning null stops the pump at that question.
function pump(G,pol,max){pol=pol||{};for(let i=0;i<(max||600);i++){const p=TB.pending(G);if(!p)return 'idle';const f=pol[p.kind]||pol['*'];if(!f)return p.kind;let any=false;
  for(const seat of p.seats.slice()){const q=TB.pending(G);if(!q||!q.seats.includes(seat))continue;const mv=TB.moves(G,seat);let m=f(mv,seat,q,G);if(typeof m==='string')m=mv.find(x=>x.k===m);if(!m)continue;const r=TB.apply(G,m);if(!r.ok)throw new Error('apply: '+r.err);any=true}
  if(!any)return p.kind}return 'max'}
const done=mv=>mv.find(m=>m.t==='done'||m.t==='seldone');
const SKIP={menu:done,castle:mv=>mv.find(m=>m.skip),wilderness:mv=>mv.find(m=>m.skip),harvest:mv=>mv.find(m=>!m.yes),shrine:done,ossuary:done,relics:done,siteBuy:done,tie:mv=>mv.find(m=>m.pass),helm:mv=>mv.find(m=>!m.yes),location:mv=>mv[0]};
const pick=l=>mv=>mv.find(m=>m.loc===l)||mv[0];
// scene: place face-down cards per Region {seat:[idR0,idR1,idR2]} (null = none), supporters {seat:[n,n,n]}, heralds {seat:loc}
function scene(G,o){o=o||{};for(const s in (o.place||{}))o.place[s].forEach((id,r)=>{if(id!=null)T.put(G,id,'down',r)});
  for(const s in (o.supp||{})){const P=G.pl[s];o.supp[s].forEach((n,r)=>{P.supp.b-=n;P.supp.r[r]+=n})}
  for(const s in (o.herald||{}))G.pl[s].herald=o.herald[s]}
// start the Summer: marker placer chooses region order `ord`; returns pump result (stops where policy returns null / is missing)
function summer(G,ord,pol){run(G,[['clashOrder'],['regionLoop',{i:0}]]);const pl=TB.pending(G).seats[0];ans(G,pl,'o'+ord.join(''));return pump(G,Object.assign({},SKIP,pol||{}))}
const infs=G=>G.pl.map(p=>p.inf);
const names=(G,ids)=>ids.map(id=>TB.cardName(G,id));
function bidGame(hands,o){o=Object.assign({facs:['clans','uprising','gathering']},o||{});const G=game(hands.length,o);hands.forEach((h,s)=>setHand(G,s,h));return G}
const BID=[['bidPlace'],['bidReveal'],['bidOrder'],['bidNext'],['bidEnd']];

// ================================================================== RULES
S('A. Setup and game length','Setup A-P of the rulebook; one setup for every player count.');
R(1,'Game length: standard 5 Rounds, short 4, extended 6.',()=>{expect([game(2,{length:'short'}).rounds,game(2).rounds,game(2,{length:'extended'}).rounds],[4,5,6]);expect(game(2).round,1)});
R(2,'The base game plays with 2, 3 or 4 players.',()=>{for(const n of [2,3,4])expect(game(n).np,n)});
R(3,'Great Road: 4 face-up Kingdom Cards; the Kingdom Deck holds the other 47 of 51 distinct cards.',()=>{const G=game(2);expect(G.road.filter(Boolean).length,4);expect(G.kdeck.length,47);expect(new Set(G.road.concat(G.kdeck)).size,51)});
R(4,'Kingdom\'s Favour starts on the Harvest Field (held by nobody), full 3 uses.',()=>{const G=game(3);expect([G.fav.h,G.fav.u],[-1,3])});
R(5,'Each player starts with 0 Influence, 0 Lore, Herald off the map, 5 Supporters on the board, Hand Size 6, no Kingdom Cards.',()=>{const G=game(4);for(const P of G.pl)expect([P.inf,P.lore,P.herald,P.supp.b,P.hs,P.ks.filter(Boolean).length],[0,0,-1,5,6,0])});
R(6,'Each player has 4 Tactic Tiles, all Unexhausted.',()=>{const G=game(4);for(const P of G.pl)expect([P.tac.length,P.tac.filter(t=>t.ex||t.burn).length],[4,0])});
R(7,'Opening Hand = the Heir plus 5 cards (6 total); Deck 8; Site of Power holds 5 cards (19-card faction deck).',()=>{const G=game(4);for(const P of G.pl){expect([P.hand.length,P.deck.length,P.site.length],[6,8,5]);truth(P.hand.includes(c(P.seat,HEIR)),'Heir in opening hand')}});
R(8,'The 14 Basic cards have Strengths 0,0,1,2,3,4,5,5,5,6,7,8,9,10 in every faction.',()=>{const G=game(4);for(const P of G.pl){const s=[];for(let k=0;k<14;k++)s.push(TB.cardInfo(G,c(P.seat,k)).strength);expect(s.sort((a,b)=>a-b),[0,0,1,2,3,4,5,5,5,6,7,8,9,10])}});
R(9,'Every faction\'s Site of Power has exactly 5 cards, each with a Lore cost, at least one an HQ.',()=>{const G=game(4);for(const P of G.pl){expect(P.site.length,5);truth(P.site.every(id=>TB.cardInfo(G,id).cost>=1),'every site card has cost >= 1');truth(P.site.some(id=>TB.cardInfo(G,id).kind==='hq'),'an HQ among the site cards')}});
R(10,'The Order Track lists every player once; the first player is the Active Player.',()=>{const G=game(4,{order:[2,0,3,1]});expect(G.order,[2,0,3,1])});
R(11,'Round 1 skips the Start-of-the-Year draw: the game opens with the simultaneous Bid.',()=>{const G=game(3);const p=TB.pending(G);expect([p.kind,p.simul,p.seats.length],['bid',true,3]);for(const P of G.pl)expect(P.hand.length,6)});

S('B. Start of the Year','Round 2 onward: draw, Attrition, Order Track.');
R(12,'Start of the year: every player draws up to Hand Size.',()=>{const G=game(2);G.round=2;for(const P of G.pl){T.put(G,P.hand[0],'disc');T.put(G,P.hand[0],'disc')}run(G,[['startYear']]);for(const P of G.pl)expect(P.hand.length,6)});
R(13,'Attrition: must draw from an empty Deck -> Discard Pile shuffled into a new Deck and Hand Size -1, then draw to the new size.',()=>{const G=game(2);G.round=2;const P=G.pl[0];for(const id of P.deck.slice())T.put(G,id,'disc');for(const id of P.hand.slice(0,3))T.put(G,id,'disc');run(G,[['startYear']]);expect([P.hs,P.hand.length],[5,5]);truth(P.deck.length>0,'new deck from the Discard Pile')});
R(14,'Attrition never lowers Hand Size below 3.',()=>{const G=game(2);G.round=2;const P=G.pl[0];P.hs=3;setHand(G,0,[c(0,F1),c(0,F2)]);for(const id of P.deck.slice())T.put(G,id,'disc');expect(P.deck.length,0);run(G,[['startYear']]);expect([P.hs,P.hand.length],[3,3])});
R(15,'No Attrition when no draw is needed (Hand already full, Deck empty).',()=>{const G=game(2);G.round=2;const P=G.pl[0];for(const id of P.deck.slice())T.put(G,id,'disc');expect(P.hand.length,6);run(G,[['startYear']]);expect([P.hs,P.deck.length],[6,0])});
R(16,'Attrition shuffles only the Discard Pile: the Lost Pile is not reshuffled.',()=>{const G=game(2);G.round=2;const P=G.pl[0];for(const id of P.deck.slice())T.put(G,id,'disc');T.put(G,c(0,F1),'lost');T.put(G,c(0,F2),'hand');for(const id of P.hand.slice(0,3))T.put(G,id,'disc');run(G,[['startYear']]);truth(!P.deck.includes(c(0,F1))&&!P.hand.includes(c(0,F1)),'Lost card stays in Lost Pile');truth(G.lost.includes(c(0,F1)),'still in Lost Pile')});
R(17,'Order Track: sorted by Influence, most first.',()=>{const G=game(3);G.round=2;[2,5,3].forEach((v,i)=>G.pl[i].inf=v);run(G,[['startYear']]);expect(G.order,[1,2,0])});
R(18,'Order Track ties reverse the previous relative order of the tied players (two tied).',()=>{const G=game(3,{order:[0,1,2]});G.round=2;G.pl[0].inf=4;G.pl[1].inf=4;G.pl[2].inf=1;run(G,[['startYear']]);expect(G.order,[1,0,2])});
R(19,'Order Track ties reverse the previous relative order (all four tied).',()=>{const G=game(4,{order:[0,1,2,3]});G.round=2;for(const P of G.pl)P.inf=3;run(G,[['startYear']]);expect(G.order,[3,2,1,0])});

S('C. Spring: bids and Kingdom Cards','Place Bids, Resolve Bids, Great Road repopulation.');
const HANDS=[[c(0,C6),c(0,F1),c(0,F2),c(0,F3),c(0,F4),c(0,RUSE)],[c(1,C8),c(1,F1),c(1,F2),c(1,F3),c(1,F4),c(1,RUSE)],[c(2,C6),c(2,F1),c(2,F2),c(2,F3),c(2,F4),c(2,RUSE)]];
R(20,'Bids are placed simultaneously and secretly: each player with cards chooses exactly one card from Hand.',()=>{const G=bidGame(HANDS);const p=TB.pending(G);expect([p.kind,p.simul,p.seats],['bid',true,[0,1,2]]);ans(G,0,'b:'+c(0,C6));const V=TB.view(G,1);expect(V.pl[0].bid<0,true);expect(G.pl[0].hand.length,5)});
R(21,'Bidding Strength is the printed Strength of the Bidding card; bids resolve highest first.',()=>{const G=bidGame([[c(0,AGENT),c(0,F1),c(0,F2),c(0,F3),c(0,F4),c(0,RUSE)],[c(1,C8),c(1,F1),c(1,F2),c(1,F3),c(1,F4),c(1,RUSE)]]);run(G,[['bidPlace'],['bidReveal'],['bidOrder']]);ans(G,0,'b:'+c(0,AGENT));ans(G,1,'b:'+c(1,C8));expect([G.bstr,G.bq],[[5,8],[1,0]])});
R(22,'Bid ties are resolved by Order Track position (higher first).',()=>{const G=bidGame(HANDS,{order:[2,0,1]});run(G,[['bidPlace'],['bidReveal'],['bidOrder']]);ans(G,0,'b:'+c(0,C6));ans(G,1,'b:'+c(1,C8));ans(G,2,'b:'+c(2,C6));expect(G.bq,[1,2,0])});
R(23,'Bid option I: take a face-up Great Road card and Occupy it; the Bidding card slides under it.',()=>{const G=bidGame(HANDS.slice(0,2));const kc=G.road[3];run(G,BID);ans(G,0,'b:'+c(0,C6));ans(G,1,'b:'+c(1,C8));ans(G,1,'gr:3');expect([G.pl[1].ks[0].kc,G.pl[1].ks[0].occ],[kc,c(1,C8)]);truth(!G.pl[1].hand.includes(c(1,C8)),'bid card not in hand')});
R(24,'Bid option III: take the Bidding card back into Hand.',()=>{const G=bidGame(HANDS.slice(0,2));run(G,BID);ans(G,0,'b:'+c(0,C6));ans(G,1,'b:'+c(1,C8));ans(G,1,'gr:3');ans(G,0,'ret');truth(G.pl[0].hand.includes(c(0,C6)),'bid card back in hand')});
function stealScene(my,occ,facs){const hands=[[my,c(0,F1),c(0,F2),c(0,F3),c(0,RUSE),c(0,TRADER)],[c(1,C8),c(1,F1),c(1,F2),c(1,F3),c(1,F4),c(1,RUSE)]];const G=bidGame(hands,facs?{facs}:{});T.giveKC(G,1,13,c(1,F1),0);T.put(G,occ,'occ',[1,0]);
  run(G,BID);ans(G,0,'b:'+my);ans(G,1,'b:'+c(1,C8));ans(G,1,'ret');return G}
R(25,'Bid option II: steal an opponent\'s Occupied Kingdom Card when your Bidding Strength is strictly higher than the occupier\'s Strength.',()=>{const G=stealScene(c(0,C7),c(1,F4));truth(TB.moves(G,0).some(m=>m.t==='steal'),'steal offered at 7 vs 4')});
R(26,'A steal needs STRICTLY higher: equal Strength cannot steal.',()=>{const G=stealScene(c(0,F4),c(1,F4));truth(!TB.moves(G,0).some(m=>m.t==='steal'),'no steal at 4 vs 4')});
R(27,'After a steal the occupier returns to its owner\'s Hand and the thief Occupies the card with the Bidding card.',()=>{const G=stealScene(c(0,C7),c(1,F4));ans(G,0,m=>m.t==='steal');expect([G.pl[0].ks[0].kc,G.pl[0].ks[0].occ,G.pl[1].ks[0]],[13,c(0,C7),null]);truth(G.pl[1].hand.includes(c(1,F4)),'victim\'s occupier back in hand')});
function twoKC(){const G=bidGame(HANDS.slice(0,2));T.giveKC(G,0,13,c(0,F1),0);T.giveKC(G,0,14,c(0,F2),1);T.road(G,3,20);run(G,BID);ans(G,0,'b:'+c(0,C6));ans(G,1,'b:'+c(1,C8));ans(G,1,'ret');ans(G,0,'gr:3');return G}
R(28,'A player holds at most two Kingdom Cards: a third must replace one (old card discarded, its occupier returns to Hand).',()=>{const G=twoKC();expect(kind(G),'slot');ans(G,0,'sl0');expect([G.pl[0].ks.filter(Boolean).length,G.pl[0].ks[0].kc],[2,20]);truth(G.kdisc.includes(13),'old card in Kingdom Discard');truth(G.pl[0].hand.includes(c(0,F1)),'old occupier in hand')});
R(29,'A new Kingdom Card may replace an occupied space even while the other space is empty.',()=>{const G=bidGame(HANDS.slice(0,2));T.giveKC(G,0,13,c(0,F1),0);T.road(G,3,20);run(G,BID);ans(G,0,'b:'+c(0,C6));ans(G,1,'b:'+c(1,C8));ans(G,1,'ret');ans(G,0,'gr:3');expect(kind(G),'slot');ans(G,0,'sl0');expect(G.pl[0].ks[0].kc,20)});
R(30,'Repopulating after a taken card: discard the rightmost remaining card, slide the rest right, refill to 4 face-up.',()=>{const G=game(2);const r=G.road.slice();G.taken=true;G.road[0]=0;run(G,[['bidEnd']]);truth(G.kdisc.includes(r[3]),'rightmost discarded');expect(G.road.filter(Boolean).length,4);expect(G.road[3],r[2])});
R(31,'Repopulating when nothing was taken: discard the two rightmost cards.',()=>{const G=game(2);const r=G.road.slice();G.taken=false;run(G,[['bidEnd']]);truth(G.kdisc.includes(r[3])&&G.kdisc.includes(r[2]),'two rightmost discarded');expect([G.road[3],G.road[2]],[r[1],r[0]]);expect(G.road.filter(Boolean).length,4)});
R(32,'When the Kingdom Deck runs out the Kingdom Discard is shuffled into a new Kingdom Deck.',()=>{const G=game(2);G.kdisc=G.kdisc.concat(G.kdeck.splice(0));G.taken=true;run(G,[['bidEnd']]);expect(G.road.filter(Boolean).length,4);truth(G.kdeck.length>0,'new deck built from discard');expect(TB.invariants(G),[])});
R(33,'Taking a Kingdom Card outside the Bid step refills the Great Road without a discard.',()=>{const G=game(2);const r=G.road.slice();G.road[3]=0;I.setG(G);I.refillRoad(0);expect([G.kdisc.length,G.road.filter(Boolean).length],[0,4]);expect(G.road.slice(1),[r[0],r[1],r[2]])});
R(34,'A card returning to a full Hand goes on top of its Deck instead.',()=>{const G=game(2);const P=G.pl[0];P.hs=3;setHand(G,0,[c(0,F1),c(0,F2),c(0,F3)]);I.setG(G);I.toHand(0,c(0,C6));expect([P.hand.length,P.deck[0]],[3,c(0,C6)])});
R(35,'A player with no cards in Hand makes no bid and the bid step still completes.',()=>{const G=bidGame(HANDS.slice(0,2));setHand(G,0,[]);run(G,[['bidPlace']]);expect(TB.pending(G).seats,[1])});

S('D. Spring: Heralds, face-down cards, Supporters');
R(36,'Heralds are placed in turn order on any Location; several Heralds may share a Location.',()=>{const G=game(3,{order:[2,0,1]});run(G,[['heralds',{i:0}]]);expect(TB.pending(G).seats,[2]);ans(G,2,'l3');expect(TB.pending(G).seats,[0]);ans(G,0,'l3');ans(G,1,'l0');expect(G.pl.map(p=>p.herald),[3,0,3])});
R(37,'Each player places exactly one face-down card next to each of the 3 Regions (simultaneous).',()=>{const G=game(2);for(const s of [0,1])setHand(G,s,[c(s,F1),c(s,F2),c(s,F3),c(s,F4),c(s,C6),c(s,C7)]);run(G,[['placeCards']]);expect(TB.pending(G).simul,true);for(const s of [0,1]){ans(G,s,'p:'+c(s,C6));ans(G,s,'p:'+c(s,C7));ans(G,s,'p:'+c(s,F1))}expect([0,1,2].map(r=>G.reg[r].down.length),[2,2,2]);expect(G.pl[0].hand.length,3)});
R(38,'A player with fewer than 3 cards places first, one card per Region of their choice.',()=>{const G=game(3,{order:[0,1,2]});setHand(G,1,[c(1,F1),c(1,F2)]);run(G,[['placeCards']]);expect(TB.pending(G).seats,[1]);ans(G,1,'p:'+c(1,F1)+':2');ans(G,1,'p:'+c(1,F2)+':0');expect([G.reg[2].down,G.reg[0].down],[[c(1,F1)],[c(1,F2)]]);expect(TB.pending(G).seats.sort(),[0,2])});
R(39,'Face-down cards are hidden from opponents until the Clash reveal.',()=>{const G=game(2);scene(G,{place:{1:[c(1,C9),null,null]}});const V=TB.view(G,0);expect(V.reg[0].down[0]<0,true);const W=TB.view(G,1);expect(W.reg[0].down[0],c(1,C9))});
R(40,'Spring Action Step: Supporters can be placed from the board onto Regions, any number, any Region.',()=>{const G=game(2);run(G,[['menus',{step:'spring',i:0}]]);ans(G,0,m=>m.p&&m.p.r===1&&m.p.n===3);expect([G.pl[0].supp.r,G.pl[0].supp.b],[[0,3,0],2])});
R(41,'Action Steps run in turn order and every Action is optional.',()=>{const G=game(3,{order:[1,2,0]});run(G,[['menus',{step:'spring',i:0}]]);expect(TB.pending(G).seats,[1]);ans(G,1,'done');expect(TB.pending(G).seats,[2]);ans(G,2,'done');ans(G,0,'done');expect(TB.pending(G),null)});

S('E. Summer: Clashes');
const LOC={castle:0,wilderness:1,harvest:2,battlefield:3,shrine:4,necropolis:5};
// seat 0 wins the Region holding `loc` with a 9, seat 1 has a 1 there; every other Region is empty for both
function winAt(G,loc,pol,extra){const r=loc>>1;emptyHands(G);T.put(G,c(0,C9),'down',r);T.put(G,c(1,F1),'down',r);if(extra)extra(G);return summer(G,[r].concat([0,1,2].filter(x=>x!==r)),Object.assign({location:pick(loc)},pol||{}))}
R(42,'The last player on the Order Track places the Clash Markers (chooses the Region order).',()=>{const G=game(3,{order:[2,0,1]});run(G,[['clashOrder']]);expect(TB.pending(G).seats,[1])});
R(43,'Clashes are resolved Region by Region in the marker order.',()=>{const G=game(2);emptyHands(G);scene(G,{place:{0:[c(0,C9),c(0,F1),null],1:[c(1,C6),c(1,F2),null]}});const order=[];summer(G,[2,1,0],{location:(mv,s,q,GG)=>{order.push(GG.clash.r);return mv[0]}});expect(order,[1,0])});
R(44,'Clash step A: face-down cards are revealed and become Active.',()=>{const G=game(2);emptyHands(G);scene(G,{place:{0:[c(0,C9)],1:[c(1,C6)]}});run(G,[['clashOrder'],['regionLoop',{i:0}]]);ans(G,TB.pending(G).seats[0],'o012');expect(G.reg[0].up.slice().sort((a,b)=>a-b),[c(0,C9),c(1,C6)].sort((a,b)=>a-b));expect(G.reg[0].down,[])});
R(45,'A side\'s Strength is the sum of its Active cards\' Strength plus 1 per Supporter in the Region.',()=>{const G=game(2);emptyHands(G);scene(G,{place:{0:[c(0,F2),null,null],1:[c(1,C6),null,null]},supp:{0:[3,0,0]}});summer(G,[0,1,2],{location:null});expect(G.clash.tot,{0:5,1:6})});
R(46,'A player with no Active cards still competes with Supporters.',()=>{const G=game(2);emptyHands(G);scene(G,{place:{1:[c(1,F1),null,null]},supp:{0:[2,0,0]}});T.put(G,c(0,F1),'down',0);G.reg[0].down=G.reg[0].down.filter(id=>id!==c(0,F1));T.put(G,c(1,F1),'down',0);summer(G,[0,1,2],{location:null});expect(G.clash.tot,{0:2,1:1})});
R(47,'The highest total Strength wins the Clash.',()=>{const G=game(2);winAt(G,LOC.castle);expect(G.pl[0].inf,1);expect(G.pl[1].inf,0)});
R(48,'The winner chooses ONE of the two Locations of that Region (offered: exactly those two).',()=>{const G=game(2);emptyHands(G);T.put(G,c(0,C9),'down',1);T.put(G,c(1,F1),'down',1);let offered=null;summer(G,[1,0,2],{location:mv=>{offered=mv.map(m=>m.loc).sort();return mv[0]}});expect(offered,[2,3])});
R(49,'Castle (Highlands) rewards 1 Influence and a Govern with an Active or Hand card.',()=>{const G=game(2);winAt(G,LOC.castle,{castle:mv=>mv.find(m=>m.c==='oaths'&&m.id===c(0,C9))});expect([G.pl[0].inf,G.council.oaths],[1,[c(0,C9)]])});
R(50,'Wilderness (Highlands) rewards 1 Influence and a Journey with an Active or Hand card.',()=>{const G=game(2);winAt(G,LOC.wilderness,{wilderness:mv=>mv.find(m=>m.id===c(0,C9)),siteBuy:done});expect([G.pl[0].inf,G.pl[0].lore],[1,1]);truth(G.pl[0].disc.includes(c(0,C9)),'Pathfinder captain goes to Discard after Journey')});
R(51,'Harvest Field (Plateau) rewards 1 Influence and the Kingdom\'s Favour disc.',()=>{const G=game(2);winAt(G,LOC.harvest,{harvest:mv=>mv.find(m=>m.yes)});expect([G.pl[0].inf,G.fav],[1,{h:0,u:3}])});
R(52,'Battlefield (Plateau) rewards 2 Influence and nothing else.',()=>{const G=game(2);winAt(G,LOC.battlefield);expect(G.pl[0].inf,2)});
R(53,'Shrine (Lowlands) rewards 1 Influence and lets you move up to three cards to the bottom of your Deck.',()=>{const G=game(2);winAt(G,LOC.shrine,{shrine:null});expect(kind(G),'shrine');ans(G,0,'s:'+c(0,C9));expect([G.pl[0].inf,G.pl[0].deck[G.pl[0].deck.length-1]],[1,c(0,C9)]);});
R(54,'Necropolis (Lowlands) rewards 1 Influence; shuffle Discard Pile and draw up to three from it (hand limit applies).',()=>{const G=game(2);emptyHands(G);const P=G.pl[0];for(const k of [F1,F2,F3,F4])T.put(G,c(0,k),'disc');T.put(G,c(0,C9),'down',2);T.put(G,c(1,F1),'down',2);summer(G,[2,0,1],{location:pick(5),ossuary:done});expect([P.inf,P.hand.length,P.disc.length],[1,3,1])});
R(55,'Herald Reward: if your Herald is on the chosen Location you gain 1 Influence (in addition to the Location Reward).',()=>{const G=game(2);winAt(G,LOC.battlefield,null,g=>{g.pl[0].herald=3});expect(G.pl[0].inf,3)});
R(56,'Herald Reward: also steal 1 Influence from each opponent whose Herald is on that Location.',()=>{const G=game(3);winAt(G,LOC.battlefield,null,g=>{g.pl[0].herald=3;g.pl[1].herald=3;g.pl[2].herald=3;g.pl[1].inf=1;g.pl[2].inf=5});expect(infs(G),[2+1+2,0,4])});
R(57,'No Herald Reward when your Herald stands elsewhere.',()=>{const G=game(2);winAt(G,LOC.battlefield,null,g=>{g.pl[0].herald=0;g.pl[1].herald=3});expect(infs(G),[2,0])});
R(58,'Stealing takes only what the victim has: Influence never goes below 0.',()=>{const G=game(2);winAt(G,LOC.battlefield,null,g=>{g.pl[0].herald=3;g.pl[1].herald=3;g.pl[1].inf=0});truth(G.pl[1].inf>=0,'victim stays at 0');expect(infs(G),[3,0])});
R(59,'A tied Clash: tied players in turn order may play a face-down card from Hand to start a new Clash, or pass.',()=>{const G=game(2);emptyHands(G);scene(G,{place:{0:[c(0,F2)],1:[c(1,F2)]}});T.put(G,c(0,C9),'hand');T.put(G,c(1,C6),'hand');summer(G,[0,1,2],{tie:null});expect([kind(G),TB.pending(G).seats],['tie',[0]]);ans(G,0,'c'+c(0,C9));expect(TB.pending(G).seats,[1])});
R(60,'If every tied player passes, the Region ends in a tie: nobody gains rewards.',()=>{const G=game(2);emptyHands(G);scene(G,{place:{0:[c(0,F2)],1:[c(1,F2)]}});T.put(G,c(0,C9),'hand');summer(G,[0,1,2],{tie:mv=>mv.find(m=>m.pass)});expect(infs(G),[0,0])});
R(61,'In the new Clash only newly played cards count (earlier cards and Supporters are ignored); players who passed still take part.',()=>{const G=game(2);emptyHands(G);scene(G,{place:{0:[c(0,F2)],1:[c(1,F2)]},supp:{0:[1,0,0],1:[1,0,0]}});T.put(G,c(0,F1),'hand');summer(G,[0,1,2],{tie:(mv,s)=>s===0?mv.find(m=>m.id===c(0,F1)):mv.find(m=>m.pass),location:null});expect(G.clash.tot,{0:1,1:0})});
R(62,'Deadly: all opposing Active cards in the Clash are Eliminated to the Lost Pile (and do not count for Strength).',()=>{const G=game(2);emptyHands(G);scene(G,{place:{0:[c(0,AGENT)],1:[c(1,C9)]}});summer(G,[0,1,2],{location:null});truth(G.lost.includes(c(1,C9)),'captain in Lost Pile');expect(G.clash.tot,{0:5,1:0})});
R(63,'Deadly cards facing each other Eliminate each other.',()=>{const G=game(2);emptyHands(G);scene(G,{place:{0:[c(0,AGENT)],1:[c(1,AGENT)]}});summer(G,[0,1,2],{location:null});expect(G.lost.slice().sort((a,b)=>a-b),[c(0,AGENT),c(1,AGENT)])});
R(64,'Invulnerable cards are not Eliminated by Deadly (a Deadly Heir kills the captain but not the Invulnerable follower).',()=>{const G=game(2);emptyHands(G);G.rm.lanes.push(0);scene(G,{place:{0:[c(0,HEIR)],1:[c(1,F4)]}});T.put(G,c(1,C9),'down',0);summer(G,[0,1,2],{location:null});truth(G.reg[0].up.includes(c(1,F4))&&G.lost.includes(c(1,C9)),'follower alive, captain in Lost Pile');expect(G.clash.tot,{0:10,1:4})});
R(65,'Resilient cards that are Eliminated go to the Discard Pile instead of the Lost Pile.',()=>{const G=game(2);emptyHands(G);scene(G,{place:{0:[c(0,AGENT)],1:[c(1,HEIR)]}});summer(G,[0,1,2],{location:null});truth(G.pl[1].disc.includes(c(1,HEIR))&&!G.lost.includes(c(1,HEIR)),'heir in Discard Pile only')});
function dayClash(G,fn){emptyHands(G);fn(G);run(G,[['clashOrder'],['regionLoop',{i:0}]]);ans(G,TB.pending(G).seats[0],'o012');pump(G,{menu:null,'*':null})}
R(66,'Ambush (Day): add a face-down card from Hand; it is revealed after the Day step and counts.',()=>{const G=game(2);dayClash(G,g=>{scene(g,{place:{0:[c(0,RUSE)],1:[c(1,F1)]}});T.put(g,c(0,C9),'hand')});ans(G,0,m=>m.a==='cmd:ambush');ans(G,0,'c'+c(0,C9));pump(G,Object.assign({},SKIP,{location:null}));expect(G.clash.tot[0],9)});
R(67,'Retreat (Day): send Active cards back to Hand.',()=>{const G=game(2);dayClash(G,g=>{scene(g,{place:{0:[c(0,RUSE)],1:[c(1,F1)]}})});ans(G,0,m=>m.a==='cmd:retreat');ans(G,0,'s:'+c(0,RUSE));ans(G,0,'done');truth(G.pl[0].hand.includes(c(0,RUSE)),'ruse back in hand')});
R(68,'Retreat (Day): the Herald and Supporters in the Region may go back to their boards.',()=>{const G=game(2);dayClash(G,g=>{scene(g,{place:{0:[c(0,RUSE)],1:[c(1,F1)]},supp:{0:[2,0,0]},herald:{0:0}})});ans(G,0,m=>m.a==='cmd:retreat');ans(G,0,'s:H');ans(G,0,'s:S');ans(G,0,'done');expect([G.pl[0].herald,G.pl[0].supp.b,G.pl[0].supp.r[0]],[-1,5,0])});
R(69,'Flank (Day): move the card to a different unresolved Region, where it is Active.',()=>{const G=game(2);dayClash(G,g=>{scene(g,{place:{0:[c(0,CAV)],1:[c(1,F1)]}})});ans(G,0,m=>m.a==='cmd:flank');ans(G,0,'r2');expect(G.reg[2].up.includes(c(0,CAV)),true);expect(G.reg[0].up.includes(c(0,CAV)),false)});
R(70,'Flank cannot target a Region whose Clash is already resolved.',()=>{const G=game(2);emptyHands(G);scene(G,{place:{0:[c(0,F1)],1:[c(1,F2)],2:[c(0,CAV)]}});run(G,[['clashOrder'],['regionLoop',{i:0}]]);ans(G,TB.pending(G).seats[0],'o012');pump(G,Object.assign({},SKIP,{menu:(mv,s,q,GG)=>GG.clash.r===2?null:done(mv),location:mv=>mv[0]}));const m=TB.moves(G,0).filter(x=>x.a==='cmd:flank');truth(m.length===0,'no Flank offered with Regions I and II resolved and none left',m.length)});
R(71,'A Command is used at most once per card per Clash.',()=>{const G=game(2);dayClash(G,g=>{scene(g,{place:{0:[c(0,RUSE)],1:[c(1,F1)]}});T.put(g,c(0,C9),'hand');T.put(g,c(0,C8),'hand')});ans(G,0,m=>m.a==='cmd:ambush');ans(G,0,'c'+c(0,C9));truth(!TB.moves(G,0).some(m=>m.a==='cmd:ambush'||m.a==='cmd:retreat'),'ruse offers nothing more')});
R(72,'Day Action Step: activations run in turn order.',()=>{const G=game(2,{order:[1,0]});dayClash(G,g=>{scene(g,{place:{0:[c(0,RUSE)],1:[c(1,RUSE)]}});T.put(g,c(0,C9),'hand');T.put(g,c(1,C9),'hand')});expect(TB.pending(G).seats,[1])});
R(73,'Cards stay Active after their Clash until Winter.',()=>{const G=game(2);winAt(G,LOC.castle);truth(G.reg[0].up.includes(c(0,C9))&&G.reg[0].up.includes(c(1,F1)),'both Active cards still on the Region')});

S('F. Kingdom\'s Favour');
R(74,'Harvest Field: claim the Favour disc from the board at full uses.',()=>{const G=game(2);winAt(G,LOC.harvest,{harvest:mv=>mv.find(m=>m.yes)});expect([G.fav.h,G.fav.u],[0,3])});
R(75,'Harvest Field: the Favour may be taken from its current holder.',()=>{const G=game(2);G.fav={h:1,u:2};winAt(G,LOC.harvest,{harvest:mv=>mv.find(m=>m.yes)});expect(G.fav,{h:0,u:3})});
R(76,'Harvest Field: re-claiming a Favour you hold resets it to 3 uses.',()=>{const G=game(2);G.fav={h:0,u:1};winAt(G,LOC.harvest,{harvest:mv=>mv.find(m=>m.yes)});expect(G.fav,{h:0,u:3})});
R(77,'Using the Favour rotates it one step (3 -> 2 -> 1) and only its holder may use it.',()=>{const G=game(2);G.fav={h:0,u:3};run(G,[['menus',{step:'spring',i:0}]]);truth(TB.moves(G,0).some(m=>/^fav:/.test(m.a||'')),'holder offered the Favour');ans(G,0,m=>/^fav:/.test(m.a||''));pump(G,{favNob:mv=>mv[0],menu:null,'*':mv=>mv[0]});expect(G.fav,{h:0,u:2});const H=game(2);H.fav={h:1,u:3};run(H,[['menus',{step:'spring',i:0}]]);truth(!TB.moves(H,0).some(m=>/^fav:/.test(m.a||'')),'non-holder not offered it')});
R(78,'After the third use the Favour returns to the Harvest Field.',()=>{const G=game(2);G.fav={h:0,u:1};run(G,[['menus',{step:'spring',i:0}]]);ans(G,0,m=>/^fav:/.test(m.a||''));pump(G,{menu:null,'*':mv=>mv[0]});expect(G.fav.h,-1)});
R(79,'Nobility Favour: gain 1 Influence (or give Heirs Invulnerable for the Round).',()=>{const G=game(2);G.fav={h:0,u:3};run(G,[['menus',{step:'spring',i:0}]]);ans(G,0,m=>/^fav:/.test(m.a||''));ans(G,0,'inf');expect(G.pl[0].inf,1)});
R(80,'Clans Favour (Day): move your Herald to a Location in the current Region and up to two Supporters from other Regions to it.',()=>{const G=game(2,{facs:['clans','nobility']});G.fav={h:0,u:3};dayClash(G,g=>{scene(g,{place:{0:[c(0,F1)],1:[c(1,F1)]},supp:{0:[0,2,0]},herald:{0:5}})});ans(G,0,m=>/^fav:/.test(m.a||''));ans(G,0,'l1');ans(G,0,'r1');ans(G,0,'r1');expect([G.pl[0].herald,G.pl[0].supp.r],[1,[2,0,0]])});
R(81,'Uprising Favour (Spring): look at a Region\'s face-down cards and swap one of your face-down cards with an Occupier or a Hand card.',()=>{const G=game(2,{facs:['uprising','nobility']});G.fav={h:0,u:3};scene(G,{place:{0:[c(0,F1)],1:[c(1,C9)]}});run(G,[['menus',{step:'spring',i:0}]]);ans(G,0,m=>/^fav:/.test(m.a||''));ans(G,0,'r0');const h=G.pl[0].hand[0];ans(G,0,x=>x.mine===c(0,F1)&&x.with===h);expect([G.reg[0].down.filter(id=>id===h).length,G.pl[0].hand.includes(c(0,F1))],[1,true])});
R(82,'Gathering Favour (Autumn): move one Active card in the Region where your Herald stands to your Hand.',()=>{const G=game(2,{facs:['gathering','nobility']});G.fav={h:0,u:3};emptyHands(G);T.put(G,c(0,C9),'up',0);G.pl[0].herald=1;run(G,[['menus',{step:'autumn',i:0}]]);ans(G,0,m=>/^fav:/.test(m.a||''));ans(G,0,'c'+c(0,C9));truth(G.pl[0].hand.includes(c(0,C9)),'card in hand')});

S('G. Autumn: Govern, Journey, Lore, Commands');
function autumn(G,seat){run(G,[['menus',{step:'autumn',i:0}]]);while(TB.pending(G)&&TB.pending(G).seats[0]!==seat)ans(G,TB.pending(G).seats[0],'done')}
const act=(G,seat,name,f)=>ans(G,seat,m=>m.a===name&&(!f||f(m.p)));
R(83,'Govern (once per Autumn): move a Hand card showing at least 1 Vote into a Council of your choice.',()=>{const G=game(2);emptyHands(G);T.put(G,c(0,TRADER),'hand');autumn(G,0);act(G,0,'govern',p=>p.c==='secrets');expect(G.council.secrets,[c(0,TRADER)])});
R(84,'A card with no Votes cannot Govern.',()=>{const G=game(2);emptyHands(G);T.put(G,c(0,F1),'hand');T.put(G,c(0,RUSE),'hand');autumn(G,0);truth(!TB.moves(G,0).some(m=>m.a==='govern'),'no Govern offered')});
R(85,'Govern can be done only once per Autumn.',()=>{const G=game(2);emptyHands(G);T.put(G,c(0,TRADER),'hand');T.put(G,c(0,AGENT),'hand');autumn(G,0);act(G,0,'govern',p=>p.c==='secrets'&&p.id===c(0,TRADER));truth(!TB.moves(G,0).some(m=>m.a==='govern'),'second Govern not offered')});
R(86,'Any number of cards may sit in one Council over time.',()=>{const G=game(2);for(const k of [TRADER,AGENT,C6])T.put(G,c(0,k),'council','oaths');expect(G.council.oaths.length,3)});
R(87,'Journey (once per Autumn): a Hand card with Lore goes to the Lost Pile and you gain Lore equal to its Lore icons.',()=>{const G=game(2);emptyHands(G);T.put(G,c(0,TRADER),'hand');autumn(G,0);act(G,0,'journey');pump(G,{siteBuy:done});expect([G.pl[0].lore,G.lost.includes(c(0,TRADER))],[2,true])});
R(88,'A Pathfinder that Journeys goes to the Discard Pile instead of the Lost Pile.',()=>{const G=game(2);emptyHands(G);T.put(G,c(0,CAV),'hand');autumn(G,0);act(G,0,'journey');pump(G,{siteBuy:done});expect([G.pl[0].lore,G.pl[0].disc.includes(c(0,CAV)),G.lost.length],[1,true,0])});
R(89,'A card with no Lore cannot Journey; Journey is once per Autumn.',()=>{const G=game(2);emptyHands(G);T.put(G,c(0,RUSE),'hand');T.put(G,c(0,TRADER),'hand');T.put(G,c(0,CAV),'hand');autumn(G,0);expect(TB.moves(G,0).filter(m=>m.a==='journey').map(m=>m.p.id).sort(),[c(0,TRADER),c(0,CAV)].sort());act(G,0,'journey',p=>p.id===c(0,CAV));pump(G,{siteBuy:done});truth(!TB.moves(G,0).some(m=>m.a==='journey'),'second Journey not offered')});
function lore(G,seat,n){G.pl[seat].lore=n;run(G,[['siteBuy',{seat}]])}
R(90,'Lore may be spent on Site of Power cards: an Advanced card goes to your Hand.',()=>{const G=game(2);emptyHands(G);lore(G,0,5);expect(kind(G),'siteBuy');const id=G.pl[0].site.find(x=>TB.cardInfo(G,x).kind==='advanced'&&TB.cardInfo(G,x).cost<=2);ans(G,0,'s:'+id);ans(G,0,m=>m.t==='seldone');truth(G.pl[0].hand.includes(id),'bought card in hand');expect(G.pl[0].lore,5-TB.cardInfo(G,id).cost)});
R(91,'Lore may be spent on an HQ card: it goes to your Supply (face-up), not your Hand.',()=>{const G=game(2);emptyHands(G);lore(G,0,5);const id=G.pl[0].site.find(x=>TB.cardInfo(G,x).kind==='hq'&&TB.cardInfo(G,x).cost<=3);ans(G,0,'s:'+id);ans(G,0,m=>m.t==='seldone');truth(G.pl[0].hq.includes(id)&&!G.pl[0].hand.includes(id),'HQ in Supply')});
R(92,'An Advanced card bought with a full Hand goes on top of the Deck.',()=>{const G=game(2);const P=G.pl[0];expect(P.hand.length,6);lore(G,0,5);const id=P.site.find(x=>TB.cardInfo(G,x).kind==='advanced'&&TB.cardInfo(G,x).cost<=2);ans(G,0,'s:'+id);ans(G,0,m=>m.t==='seldone');expect([P.deck[0],P.hand.includes(id)],[id,false])});
R(93,'Unspent Lore is kept in your Supply.',()=>{const G=game(2);lore(G,0,1);expect([G.pl[0].lore,kind(G)],[1,null])});
R(94,'Rally (Autumn): return Active cards to your Hand (the Heir rallies itself).',()=>{const G=game(2);emptyHands(G);T.put(G,c(0,HEIR),'up',0);autumn(G,0);act(G,0,'cmd:rally');truth(G.pl[0].hand.includes(c(0,HEIR)),'Heir back in hand')});
R(95,'Deploy (Autumn): put a Hand card face-up (Active) next to a Region with Influence tokens on it; tokens fall off one per Winter and the card stays Active meanwhile.',()=>{const G=game(2);emptyHands(G);T.put(G,c(0,WM),'hand');autumn(G,0);act(G,0,'cmd:deploy',p=>p.r===1);truth(G.reg[1].up.includes(c(0,WM)),'Active in Region 1');run(G,[['winter']]);truth(G.reg[1].up.includes(c(0,WM)),'still Active after first Winter');run(G,[['winter']]);truth(G.pl[0].disc.includes(c(0,WM)),'in Discard after tokens are gone')});
R(96,'Autumn Action Step runs in turn order.',()=>{const G=game(3,{order:[2,1,0]});run(G,[['menus',{step:'autumn',i:0}]]);expect(TB.pending(G).seats,[2])});

S('H. Councils');
R(97,'Council of Coin: when you claim a Herald Reward you may remove your cards here and gain Influence equal to the Votes removed.',()=>{const G=game(2);T.put(G,c(0,TRADER),'council','relics');winAt(G,LOC.battlefield,{relics:mv=>mv.find(m=>m.v===c(0,TRADER))||done(mv)},g=>{g.pl[0].herald=3});expect(G.pl[0].inf,2+1+2);truth(G.pl[0].disc.includes(c(0,TRADER)),'removed card in Discard Pile')});
R(98,'Council of Whispers (Autumn): place Faction Markers equal to your Votes on Locations.',()=>{const G=game(2);T.put(G,c(0,TRADER),'council','secrets');autumn(G,0);act(G,0,'council:secrets');ans(G,0,'l3');ans(G,0,'l3');expect(G.pl[0].mk[3],2)});
R(99,'Council of Whispers: a Location with 4 of your markers is claimed for its Reward text only (no Influence number, no Herald Reward); the markers are removed.',()=>{const G=game(2);for(const k of [TRADER,AGENT])T.put(G,c(0,k),'council','secrets');G.pl[0].mk[3]=2;G.pl[0].mk[2]=0;G.pl[0].herald=3;G.pl[1].herald=3;G.pl[1].inf=3;autumn(G,0);act(G,0,'council:secrets');ans(G,0,'l3');ans(G,0,'l3');pump(G,{'*':mv=>mv[0]});expect([G.pl[0].mk[3],G.pl[0].inf,G.pl[1].inf],[0,0,3])});
R(100,'Council of Pledges (Autumn): move Supporters from the Map and/or Lost Pile to your board, up to your Votes.',()=>{const G=game(2);T.put(G,c(0,TRADER),'council','oaths');T.put(G,c(1,TRADER),'council','oaths');G.pl[0].supp.b=2;G.pl[0].supp.l=3;autumn(G,0);act(G,0,'council:oaths');expect(G.pl[0].supp.b,2+2+0)});
R(101,'Council of Pledges: +1 extra Supporter if you have strictly the most Votes there.',()=>{const G=game(2);T.put(G,c(0,TRADER),'council','oaths');G.pl[0].supp.b=0;G.pl[0].supp.l=5;autumn(G,0);act(G,0,'council:oaths');expect(G.pl[0].supp.b,3)});
R(102,'Council of Pledges: no extra Supporter when Votes are tied for most.',()=>{const G=game(2);T.put(G,c(0,TRADER),'council','oaths');T.put(G,c(1,TRADER),'council','oaths');G.pl[0].supp.b=0;G.pl[0].supp.l=5;autumn(G,0);act(G,0,'council:oaths');expect(G.pl[0].supp.b,2)});
R(103,'Council of Pledges needs at least 1 Vote there.',()=>{const G=game(2);G.pl[0].supp.l=2;G.pl[0].supp.b=3;autumn(G,0);truth(!TB.moves(G,0).some(m=>m.a==='council:oaths'),'not offered without votes')});
R(104,'Cards leaving a Council go to their owner\'s Discard Pile.',()=>{const G=game(2);T.put(G,c(1,TRADER),'council','oaths');I.setG(G);I.leaveCouncil([c(1,TRADER)],'test');truth(G.pl[1].disc.includes(c(1,TRADER))&&G.council.oaths.length===0,'owner Discard Pile')});
R(105,'Castle Reward: Govern discards every OTHER card in the chosen Council (including your own).',()=>{const G=game(2);T.put(G,c(0,AGENT),'council','secrets');T.put(G,c(1,TRADER),'council','secrets');winAt(G,LOC.castle,{castle:mv=>mv.find(m=>m.c==='secrets'&&m.id===c(0,C9))||mv.find(m=>m.c==='secrets')});truth(G.council.secrets.length<=1,'at most the new card remains',G.council.secrets.length)});
R(106,'Cards in a Council are not Active (they cannot Clash).',()=>{const G=game(2);T.put(G,c(0,C9),'council','oaths');emptyHands(G);scene(G,{place:{0:[c(0,F2)],1:[c(1,F1)]}});summer(G,[0,1,2],{location:null});truth(!G.clash.cards[0].includes(c(0,C9)),'council card absent from Clash')});

S('I. Winter');
function winterGame(){const G=game(2);emptyHands(G);return G}
R(107,'Winter cleanup: Heralds on the Map return to their boards.',()=>{const G=winterGame();G.pl[0].herald=4;run(G,[['winter']]);expect(G.pl[0].herald,-1)});
R(108,'Winter cleanup: Supporters on the Map go to the Lost Pile.',()=>{const G=winterGame();scene(G,{supp:{0:[2,1,0]}});run(G,[['winter']]);expect([G.pl[0].supp.b,G.pl[0].supp.l,G.pl[0].supp.r],[2,3,[0,0,0]])});
R(109,'Winter cleanup: Active cards without Influence tokens go to their owner\'s Discard Pile.',()=>{const G=winterGame();T.put(G,c(0,C9),'up',0);T.put(G,c(1,C6),'up',1);run(G,[['winter']]);truth(G.pl[0].disc.includes(c(0,C9))&&G.pl[1].disc.includes(c(1,C6))&&G.reg[0].up.length===0,'in Discard Piles')});
R(110,'Winter cleanup: an Active card with an Influence token loses 1 token and stays Active.',()=>{const G=winterGame();T.put(G,c(0,WM),'up',0);I.setG(G);G.cmod[c(0,WM)]={tok:2};run(G,[['winter']]);expect([G.reg[0].up.includes(c(0,WM)),G.cmod[c(0,WM)].tok],[true,1])});
R(111,'Winter ends the Round: the Round Marker advances and the next Round begins (Round 2 draws and sorts).',()=>{const G=winterGame();G.round=1;run(G,[['winter']]);expect(G.round,2);expect(kind(G),'bid')});
R(112,'The game ends after the final Round (4 / 5 / 6 by length).',()=>{for(const [len,n] of [['short',4],['standard',5],['extended',6]]){const G=game(2,{length:len});G.round=n-1;run(G,[['winter']]);expect([len,G.phase==='over'],[len,false]);G.round=n;run(G,[['winter']]);expect([len,G.phase],[len,'over'])}});
R(113,'Hand Size can never exceed 8.',()=>{const G=game(2);const P=G.pl[0];P.hs=8;T.giveKC(G,0,17,P.hand[0],0);expect(P.hs,8)});
R(114,'A Hand over its Hand Size must discard down.',()=>{const G=game(2);const P=G.pl[0];setHand(G,0,[c(0,F1),c(0,F2),c(0,F3),c(0,F4),c(0,C6)]);P.hs=4;I.setG(G);I.AG.enforceHand({seat:0});expect(kind(G),'discardDown');ans(G,0,'s:'+c(0,F1));expect(P.hand.length,4)});

S('J. End of the game, scoring, ties');
function endWith(G){G.round=G.rounds;run(G,[['winter']])}
R(115,'The player with the most Influence in their Supply wins.',()=>{const G=game(3);[5,9,7].forEach((v,i)=>G.pl[i].inf=v);endWith(G);expect(TB.winner(G),1)});
R(116,'Site of Power empty at the end: gain 1 Influence per 2 Lore in Supply before the tally.',()=>{const G=game(2);G.pl[0].inf=4;G.pl[0].lore=5;G.pl[0].site=[];G.pl[1].inf=6;endWith(G);expect(G.pl[0].inf,6)});
R(117,'No Lore bonus while any Site of Power card remains.',()=>{const G=game(2);G.pl[0].inf=4;G.pl[0].lore=5;endWith(G);expect(G.pl[0].inf,4)});
R(118,'Tiebreaker 1: the tied player holding the Kingdom\'s Favour wins.',()=>{const G=game(3,{order:[0,1,2]});[7,7,3].forEach((v,i)=>G.pl[i].inf=v);G.fav={h:1,u:3};endWith(G);expect(TB.winner(G),1)});
R(119,'Tiebreaker 2: with no Favour holder among the tied, the higher Order Track position wins.',()=>{const G=game(3,{order:[2,0,1]});[7,7,3].forEach((v,i)=>G.pl[i].inf=v);G.pl[2].inf=7;G.pl[0].inf=3;G.pl[1].inf=7;endWith(G);expect(TB.winner(G),2)});
R(120,'The Favour breaks a tie even against a higher Order Track position.',()=>{const G=game(2,{order:[0,1]});G.pl[0].inf=5;G.pl[1].inf=5;G.fav={h:1,u:2};endWith(G);expect(TB.winner(G),1)});
R(121,'A whole game plays through to the end with no negative Influence and every card accounted for.',()=>{const G=game(3,{seed:5});let n=0;while(G.phase!=='over'&&n++<6000){const p=TB.pending(G);const mv=TB.moves(G,p.seats[0]);const nonDone=mv.filter(m=>m.t!=='done'&&m.t!=='seldone');const m=(n%4===0?mv[0]:(nonDone.length?nonDone[(n*7)%nonDone.length]:mv[0]));const r=TB.apply(G,m);if(!r.ok)throw new Error('apply '+r.err)}expect([G.phase,Math.min(...infs(G))>=0,TB.invariants(G)],['over',true,[]])});
R(122,'The game does not end early when someone reaches a high Influence total: play continues to the final Round.',()=>{const G=game(2);G.pl[0].inf=30;G.round=2;run(G,[['winter']]);expect([G.phase!=='over',G.round],[true,3])});
R(123,'Final standings put equal-Influence players in the Favour/Order Track order (ranking list is a full ordering).',()=>{const G=game(3,{order:[1,2,0]});[4,4,4].forEach((v,i)=>G.pl[i].inf=v);G.fav={h:2,u:3};endWith(G);expect(G.over.ranking,[2,1,0])});

S('K. The 14 Basic cards (printed data)');
// [Strength, archetype, traits, commands, votes, lore] per rulebook basic deck, index = card k 0..13
const BASIC_EXP=[[0,'ruse',['inv'],['ambret'],0,0],[0,'trader',[],['rally'],2,2],[1,'follower',['inv'],[],0,1],[2,'follower',['inv'],[],0,1],[3,'follower',['inv'],[],0,1],[4,'follower',['inv'],[],0,1],[5,'agent',[],['deadly'],2,1],[5,'cavalry',['path'],['flank'],1,1],[5,'war_machine',['inv'],['deploy'],0,0],[6,'captain',['path'],[],1,1],[7,'captain',['path'],[],1,1],[8,'captain',['path'],[],1,1],[9,'captain',['path'],[],1,1],[10,'heir',['path','res'],['rally'],1,1]];
BASIC_EXP.forEach((e,k)=>R(124+k,'Basic card '+k+': Strength '+e[0]+', '+e[1]+(e[2].length?', '+e[2].join('+'):'')+(e[3].length?', '+e[3].join('+'):'')+', '+e[4]+' Vote(s), '+e[5]+' Lore.',()=>{const G=game(4);for(const P of G.pl){const i=TB.cardInfo(G,c(P.seat,k));expect([i.strength,i.archetype,i.traits.slice().sort(),i.commands.slice().sort(),i.votes,i.lore],[e[0],e[1],e[2].slice().sort(),e[3].slice().sort(),e[4],e[5]])}}));
const NB=124+BASIC_EXP.length;   // next rule number

S('L. Kingdom Cards, Tactics and Site cards (sampled powers)','Not every one of the 51 Kingdom Cards / 16 Tactics / 19 Site cards has its own rule here; the ones below are the powers that change core rules.');
R(NB,'Sentinel Towers: +5 to the Bidding card, +1 Influence for resolving first, and you may not steal.',()=>{const G=bidGame([[c(0,F4),c(0,F1),c(0,F2),c(0,F3),c(0,C6),c(0,RUSE)],[c(1,C8),c(1,F1),c(1,F2),c(1,F3),c(1,F4),c(1,RUSE)]]);T.giveKC(G,0,5,c(0,RUSE),0);run(G,BID);ans(G,0,'b:'+c(0,F4));ans(G,1,'b:'+c(1,C8));expect([G.bstr[0],G.pl[0].inf],[9,1])});
R(NB+1,'Monarch\'s Seal-Ring: +1 Hand Size on acquiring; -1 when you stop occupying it.',()=>{const G=game(2);T.giveKC(G,0,17,G.pl[0].hand[0],0);expect(G.pl[0].hs,7);I.setG(G);I.dropKC(0,0,'hand','kdisc');expect(G.pl[0].hs,6)});
R(NB+2,'Veiled Patron: absorbs one Attrition (no Hand Size loss), then is discarded.',()=>{const G=game(2);const P=G.pl[0];G.round=2;T.kcRemove(G,4);P.sup.push(4);for(const id of P.deck.slice())T.put(G,id,'disc');for(const id of P.hand.slice(0,3))T.put(G,id,'disc');run(G,[['startYear']]);expect([P.hs,P.sup.includes(4),G.kdisc.includes(4)],[6,false,true])});
R(NB+3,'Statue Wrights (Spring Action): gain 1 Influence if you have a card in a Council.',()=>{const G=game(2);T.giveKC(G,0,2,G.pl[0].hand[0],0);T.put(G,c(0,TRADER),'council','oaths');run(G,[['menus',{step:'spring',i:0}]]);act(G,0,'kc2');expect(G.pl[0].inf,1)});
R(NB+4,'Buried Hall: burning an Unexhausted Tactic gives 3 Lore (1 + 2 more).',()=>{const G=game(2);T.giveKC(G,0,6,G.pl[0].hand[0],0);run(G,[['menus',{step:'spring',i:0}]]);act(G,0,'kc6');ans(G,0,'t0');expect(G.pl[0].lore,3)});
R(NB+5,'The Lighthouse: acquire the Site of Power card with the lowest Lore cost, then discard the Lighthouse.',()=>{const G=bidGame(HANDS.slice(0,2));T.road(G,3,7);const P=G.pl[0];const lo=Math.min(...P.site.map(id=>TB.cardInfo(G,id).cost));run(G,BID);ans(G,0,'b:'+c(0,C6));ans(G,1,'b:'+c(1,C8));ans(G,1,'ret');ans(G,0,'gr:3');if(kind(G)==='lighthouse')ans(G,0,mv=>true);expect([P.site.length,G.kdisc.includes(7)],[4,true])});
R(NB+6,'Frozen Bastion: all opponents\' total Strength in that Region is halved (rounded up).',()=>{const G=game(2);emptyHands(G);T.kcRemove(G,43);G.reg[0].kc.push({n:43,o:0});scene(G,{place:{0:[c(0,F1),null,null],1:[c(1,C9),null,null]}});summer(G,[0,1,2],{location:null});expect(G.clash.tot,{0:1,1:5})});
R(NB+7,'Blade That Dreamed: +5 Strength in the current Clash, then it and its occupier are discarded.',()=>{const G=game(2);emptyHands(G);T.giveKC(G,0,46,c(0,RUSE),0);dayClash(G,g=>{scene(g,{place:{0:[c(0,F1)],1:[c(1,F2)]}})});act(G,0,'kc46');pump(G,Object.assign({},SKIP,{location:null}));expect(G.clash.tot[0],6)});
R(NB+8,'Dead King\'s Lance: an Active card gains Deadly for the Clash.',()=>{const G=game(2);emptyHands(G);T.giveKC(G,0,50,c(0,RUSE),0);dayClash(G,g=>{scene(g,{place:{0:[c(0,F1)],1:[c(1,C9)]}})});act(G,0,'kc50');pump(G,Object.assign({},SKIP,{location:null}));truth(G.lost.includes(c(1,C9)),'opposing captain eliminated');});
R(NB+9,'Crown\'s Edict (Nobility Tactic): every opponent\'s Bidding Strength becomes 0 (single use).',()=>{const G=bidGame([[c(0,C6),c(0,F1),c(0,F2),c(0,F3),c(0,F4),c(0,RUSE)],[c(1,C9),c(1,F1),c(1,F2),c(1,F3),c(1,F4),c(1,RUSE)]],{facs:['nobility','clans']});run(G,[['bidPlace'],['bidReveal'],['bidOrder']]);ans(G,0,'b:'+c(0,C6));ans(G,1,'b:'+c(1,C9));ans(G,0,'yes');expect(G.bstr,[6,0])});
R(NB+10,'Doctrine of Masonry (Nobility Tactic): Supporters give 2 Strength each for the Round and stay on the Map in Winter.',()=>{const G=game(2);emptyHands(G);scene(G,{place:{0:[c(0,F1),null,null],1:[c(1,F1),null,null]},supp:{0:[2,0,0]}});G.rm.masonry.push(0);summer(G,[0,1,2],{location:null});expect(G.clash.tot[0],1+4);run(G,[['winter']]);expect(G.pl[0].supp.l,0)});
R(NB+11,'Midnight Pressure (Uprising Tactic): each opponent discards one card per Kingdom Card you occupy.',()=>{const G=game(2,{facs:['uprising','nobility']});T.giveKC(G,0,13,G.pl[0].hand[0],0);run(G,[['menus',{step:'spring',i:0}]]);act(G,0,'t:upr_t3');ans(G,1,m=>m.t==='sel');expect(G.pl[1].hand.length,5)});
R(NB+12,'Doctrine of Tempests (Clans Tactic): its user places the Clash Markers.',()=>{const G=game(3,{facs:['clans','nobility','uprising'],order:[0,1,2]});G.rm.tempests=0;run(G,[['clashOrder']]);expect(TB.pending(G).seats,[0])});
R(NB+13,'Martial Writ (Nobility Tactic): opponents may not add cards to the locked Region in its first Clash.',()=>{const G=game(2);emptyHands(G);T.put(G,c(0,WM),'up',0);run(G,[['menus',{step:'spring',i:0}]]);const m=TB.moves(G,0).find(x=>x.a==='t:nob_t2');truth(!!m,'Martial Writ offered with an Active War Machine');ans(G,0,x=>x.k===m.k);expect(G.rm.lock[0],0)});
R(NB+14,'Grand Joust: players secretly play a card; equal Strengths are discarded, highest remaining wins a Location Reward.',()=>{const G=game(2);emptyHands(G);T.giveKC(G,0,38,c(0,RUSE),0);setHand(G,0,[c(0,C9),c(0,F1)]);setHand(G,1,[c(1,C6),c(1,F1)]);run(G,[['menus',{step:'spring',i:0}]]);act(G,0,'kc38');ans(G,0,'b:'+c(0,C9));ans(G,1,'b:'+c(1,C6));ans(G,0,'l3');expect(G.pl[0].inf,2)});

S('M. Variants the published game ships');
R(NB+15,'Solo mode against the Sim opponent is available (1 player).',()=>{let ok=true;try{TB.newGame({players:[{faction:'clans'}]})}catch(e){ok=false}expect(ok,true)});
R(NB+16,'Optional Advanced Setup: each player is dealt 5 Kingdom Cards, keeps 1 under a Hand card, the other 4 are shuffled back into the Kingdom Deck, then everyone redraws to Hand Size.',()=>{const G=TB.newGame({players:[{faction:'clans'},{faction:'nobility'}],advanced:true,seed:3,order:[0,1]});expect(kind(G),'advMull');pump(G,{advMull:mv=>mv.find(m=>!m.yes),advPick:mv=>mv[0],advOcc:mv=>mv[0],'*':null});expect([G.pl.map(P=>P.ks.filter(Boolean).length+P.sup.length+(P.ks.filter(Boolean).length?0:0)).every(n=>n===1),G.kdeck.length,G.pl.map(P=>P.hand.length),TB.invariants(G)],[true,45,[6,6],[]])});
R(NB+17,'Advanced Setup mulligan: all non-Heir Hand cards go back into the Deck, which is reshuffled; you redraw to Hand Size and still hold the Heir.',()=>{const G=TB.newGame({players:[{faction:'clans'},{faction:'nobility'}],advanced:true,seed:3,order:[0,1]});const old=G.pl[0].hand.slice();pump(G,{advMull:(mv,s)=>s===0?mv.find(m=>m.yes):mv.find(m=>!m.yes),'*':null});const P=G.pl[0];expect([P.hand.length,P.hand.includes(100*0+13),P.deck.length],[6,true,8-0]);truth(P.hand.some(id=>!old.includes(id)),'redrew at least one different card')});

S('N. Further edge rules');
R(NB+18,'Herald Reward needs the Herald on the CHOSEN Location: a Herald on the other Location of the same Region earns nothing.',()=>{const G=game(2);winAt(G,LOC.battlefield,null,g=>{g.pl[0].herald=2;g.pl[1].herald=2;g.pl[1].inf=2});expect(infs(G),[2,2])});
R(NB+19,'A Herald that Retreated (sent home) before the reward earns no Herald Reward.',()=>{const G=game(2);dayClash(G,g=>{scene(g,{place:{0:[c(0,RUSE),null,null],1:[c(1,F1),null,null]}});T.put(g,c(0,C9),'down',0);g.pl[0].herald=1});ans(G,0,m=>m.a==='cmd:retreat');ans(G,0,'s:H');ans(G,0,'done');pump(G,Object.assign({},SKIP,{location:pick(1),wilderness:mv=>mv.find(m=>m.skip)}));expect(G.pl[0].inf,1)});
R(NB+20,'Three players, two tied for the top: only the tied players take part in the new Clash.',()=>{const G=game(3);emptyHands(G);scene(G,{place:{0:[c(0,F4)],1:[c(1,F4)],2:[c(2,F1)]}});T.put(G,c(0,C9),'hand');T.put(G,c(1,F3),'hand');summer(G,[0,1,2],{tie:null});ans(G,0,'c'+c(0,C9));ans(G,1,'pass');pump(G,Object.assign({},SKIP,{location:null,tie:null}));expect(G.clash.parts,[0,1])});
R(NB+21,'A Flanked card fights in the new Region\'s Clash with its Strength.',()=>{const G=game(2);dayClash(G,g=>{scene(g,{place:{0:[c(0,CAV)],1:[c(1,F2)],2:[c(1,F1)]}})});ans(G,0,m=>m.a==='cmd:flank');ans(G,0,'r2');pump(G,Object.assign({},SKIP,{location:(mv,s,q,GG)=>GG.clash.r===2?null:mv[0]}));expect([G.clash.r,G.clash.tot[0]],[2,5])});
R(NB+22,'Council of Pledges takes Supporters from the Map (not only from the Lost Pile).',()=>{const G=game(2);T.put(G,c(0,TRADER),'council','oaths');T.put(G,c(1,TRADER),'council','oaths');scene(G,{supp:{0:[2,0,0]}});autumn(G,0);act(G,0,'council:oaths');expect([G.pl[0].supp.b,G.pl[0].supp.r[0]],[5,0])});
R(NB+23,'A bold Kingdom Card (Veiled Patron) discards the Bidding card and goes to the Supply, not the board.',()=>{const G=bidGame(HANDS.slice(0,2));T.road(G,3,4);run(G,BID);ans(G,0,'b:'+c(0,C6));ans(G,1,'b:'+c(1,C8));ans(G,1,'ret');ans(G,0,'gr:3');expect([G.pl[0].sup.includes(4),G.pl[0].ks.filter(Boolean).length,G.pl[0].disc.includes(c(0,C6))],[true,0,true])});
R(NB+24,'Winning a Clash gives the Location Reward only for the CHOSEN Location: the other Location of that Region gets nothing.',()=>{const G=game(2);winAt(G,LOC.harvest,{harvest:mv=>mv.find(m=>!m.yes)});expect([G.pl[0].inf,G.fav],[1,{h:-1,u:3}])});
R(NB+25,'Region reward is per Clash: a player may win several Regions in one Summer and collect each reward.',()=>{const G=game(2);emptyHands(G);scene(G,{place:{0:[c(0,C9),null,null],1:[c(1,F1),null,null]}});scene(G,{place:{1:[c(0,C9+0)]}});G.reg[1].down=[];T.put(G,c(0,C8),'down',1);T.put(G,c(1,F1),'down',1);T.put(G,c(0,C7),'down',2);T.put(G,c(1,F1),'down',2);G.reg[2].down=G.reg[2].down.filter((v,i,a)=>a.indexOf(v)===i);summer(G,[0,1,2],{location:pick(3)});truth(G.pl[0].inf>=3,'three Regions won, at least 1+2+1',G.pl[0].inf)});

// ================================================================== runner
if(process.argv.includes('--md')){
  const out=['# Rules checklist: The Thornbound Throne (published base game, own words)','',
  'Every numbered rule below has exactly one block in `logic-test.js` (same number). Generated by `node logic-test.js --md`; rule text is the published rulebook, never the engine\'s own data.','',
  'Sources: the publisher\'s rulebook (read via a text mirror), the notes in `rules-notes.md`, and an independent web check of the setup, phase, Council, Favour and end-of-game text. Solo mode and the card-by-card powers of all 51 Kingdom Cards / 16 Tactics / 19 Site cards are only partly covered: see section L and the "Not covered" list at the end.',''];
  for(const s of SEC){out.push('## '+s.name);if(s.note)out.push('_'+s.note+'_');out.push('');for(const r of RULES.filter(r=>r.sec===s.name))out.push(r.n+'. '+r.title);out.push('')}
  out.push('## Not covered by a numbered rule (honest gap list)','',
  '- 41 of the 51 Kingdom Cards (only those named in section L have a test) and 11 of 16 Tactics (Edict, Masonry, Midnight Pressure, Tempests, Martial Writ are tested); the 4 Favour actions are tested.',
  '- The individual powers of all 19 Site of Power cards (only buying them with Lore is tested).',
  '- Solo-mode components (Sim, Ambition/Scheme/Fog/Forge): unreadable rulebook, see GAPS.md.','');
  console.log(out.join('\n'));process.exit(0)}
let pass=0;const bad=[];
for(const r of RULES){try{r.fn();pass++}catch(e){bad.push(r);console.log('FAIL R'+r.n+': '+(e instanceof Fail?'expected '+JSON.stringify(e.exp)+', got '+JSON.stringify(e.got):'harness error: '+e.message.split('\n')[0])+'   ['+r.title.slice(0,70)+']')}}
console.log('logic-test: '+pass+' of '+RULES.length+' rules pass, '+bad.length+' fail');
process.exit(bad.length?1:0);
